var n=`0751-maraq`;var a=`world-0751`;var i=`SO`;var r=`eastern-africa`;var o=4;var s=71;var g={en:`Maraq`,ua:`Марак`};var l={en:`Maraq is a Somalia classic prepared with goat meat, yellow onion, tomato, carrot. A measured home-style version, with ingredients assigned to the cooking steps where they are used.`,ua:`Марак, страва кухні країни Сомалі зі складниками: козлятина, жовта цибуля, помідор, морква. Домашній рецепт із кількостями, прив’язаними до відповідних етапів приготування.`};var m=[{en:`Pat the main ingredients dry. Brown in a hot heavy pan in batches for about 13 minutes, turning to color all sides.`,ua:`Обсушіть основні продукти. Обсмажуйте їх порціями на добре розігрітій важкій сковороді приблизно 13 хвилин, перевертаючи для рівної скоринки.`,t:[`searing`],m:13,i:[[`goat-meat`,680,`g`],[`yellow-onion`,190,`g`],[`sunflower-oil`,40,`ml`]]},{en:`Combine the remaining ingredients, cover partly and stew gently for about 55 minutes until the flavors meld and everything is tender.`,ua:`З’єднайте решту складників, частково накрийте й тушкуйте приблизно 55 хвилин до поєднання смаків і м’якості продуктів.`,t:[`stewing`],m:55,i:[[`tomato`,300,`g`],[`carrot`,230,`g`],[`water`,980,`ml`],[`ground-cumin`,5,`g`],[`ground-coriander`,5,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`cilantro`,18,`g`],[`table-salt`,null,`to_taste`]]}];var d={slug:n,id:a,country:`SO`,region:r,servings:4,minutes:71,title:g,text:l,steps:m};export{i as country,d as default,a as id,s as minutes,r as region,o as servings,n as slug,m as steps,l as text,g as title};